<style>/* FOCO body doubling room: "a table at night".
   One dark scene, lit from the middle by FOCO. People sit around the table; everything else (kind words,
   your seat, the radio) sits beside it, quiet, so the table carries the feeling.
   Type: Fraunces (warm display serif) for the voice, Figtree for everything you read.
   Glows and soft gradients are deliberate on the table only. taste-skill-ignore */
:root {
  --night: #06030c;
  --panel: rgba(255, 255, 255, .035);
  --panel-2: rgba(255, 255, 255, .065);
  --line: rgba(255, 255, 255, .07);
  --line-2: rgba(255, 255, 255, .14);
  --text: #f6f3ff;
  --muted: #b9b1cf;
  --faint: #8f86a6;
  --violet: 124, 58, 237;
  --lilac: 196, 181, 253;
  --ember: 251, 146, 60;
  --display: "Fraunces", Georgia, serif;
  --body: "Figtree", system-ui, -apple-system, "Segoe UI", sans-serif;
  --pad: clamp(16px, 3vw, 40px);
  --r: 22px;
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; overflow-x: hidden; }
html, body { margin: 0; background: var(--night); }
body { overflow-x: hidden; }
.num { font-variant-numeric: tabular-nums; }
.bdr [hidden] { display: none !important; }
.bdr {
  font-family: var(--body); font-size: 15px; line-height: 22px; color: var(--text);
  background:
    radial-gradient(1200px 700px at 50% 16%, rgba(var(--violet), .17), transparent 70%),
    radial-gradient(900px 500px at 50% 100%, rgba(var(--violet), .08), transparent 70%),
    var(--night);
  min-height: 100vh; padding: 0 var(--pad) calc(48px + env(safe-area-inset-bottom)); overflow-x: clip;
  -webkit-font-smoothing: antialiased;
}
.bdr p { margin: 0; }
.bdr h1, .bdr h2 { margin: 0; font-weight: 600; }
.bdr a { color: inherit; }

/* Bar */
.bdr-bar { display: flex; align-items: center; gap: 12px; height: 68px; max-width: 1360px; margin: 0 auto; }
.bdr-brand img { display: block; height: 30px; width: auto; }
.bdr-live { display: flex; align-items: center; gap: 8px; color: var(--muted); font-size: 14px; margin: 0 auto 0 20px !important; }
.bdr-live-dot { position: relative; width: 8px; height: 8px; border-radius: 50%; background: #4ade80; }
.bdr-live-dot::after { content: ''; position: absolute; inset: -4px; border-radius: 50%; border: 2px solid #4ade80; animation: bdr-ping 2.4s ease-out infinite; }

/* Buttons and chips */
.bdr-btn {
  font: 600 14px/20px var(--body); height: 40px; padding: 0 20px; border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  cursor: pointer; text-decoration: none; white-space: nowrap; border: 0;
  transition: transform .15s ease, background-color .15s ease, color .15s ease;
}
.bdr-btn:active { transform: scale(.97); }
.bdr-btn-primary { background: #fff; color: #120a1f; box-shadow: 0 6px 24px -8px rgba(var(--lilac), .8); }
.bdr-btn-primary:hover { background: #efeaff; }
.bdr-btn-ghost { background: transparent; color: var(--text); box-shadow: inset 0 0 0 1px var(--line-2); }
.bdr-btn-ghost:hover { background: var(--panel-2); }
.bdr-btn-text { background: transparent; color: var(--muted); padding: 0 10px; }
.bdr-btn-text:hover { color: var(--text); }
.bdr-btn-wide { width: 100%; height: 50px; font-size: 15px; }
.bdr button:focus-visible, .bdr a:focus-visible, .bdr input:focus-visible, .bdr-hue input:focus-visible + span {
  outline: 2px solid rgb(var(--lilac)); outline-offset: 3px;
}
.bdr-chip {
  display: inline-flex; align-items: center; height: 38px; padding: 0 14px; border-radius: 999px; border: 0;
  background: var(--panel-2); color: var(--text); font: 600 13px/18px var(--body); text-decoration: none; cursor: pointer;
  transition: background-color .15s ease, transform .15s ease;
}
.bdr-chip:hover { background: rgba(255, 255, 255, .11); }
.bdr-chip:active { transform: scale(.96); }
.bdr-meta { color: var(--faint); font-size: 13px; }
.bdr-quiet { color: var(--muted); font-size: 14px; }

/* The scene */
.bdr-scene {
  max-width: 1360px; margin: 0 auto; display: grid; gap: 24px 32px;
  grid-template-columns: minmax(260px, 300px) minmax(0, 1fr) minmax(280px, 330px);
  grid-template-areas: "intro intro intro" "left centre right";
  align-items: start;
}
.bdr-intro { grid-area: intro; text-align: center; padding: 12px 0 0; }
.bdr-intro h1 {
  font-family: var(--display); font-weight: 500; font-size: clamp(36px, 5vw, 62px); line-height: 1.02;
  letter-spacing: -0.025em; font-variation-settings: "opsz" 144;
}
.bdr-intro h1 em { font-style: italic; font-weight: 400; color: rgb(var(--lilac)); }
.bdr-h1-kicker { display: block; font-family: var(--body); font-size: 15px; line-height: 20px; font-weight: 600; letter-spacing: 0; color: var(--muted); margin-bottom: 10px; }

/* Questions */
.bdr-faq { max-width: 820px; margin: 72px auto 0; }
.bdr-faq h2 { font-family: var(--display); font-weight: 500; font-size: clamp(28px, 3.4vw, 40px); line-height: 1.1; letter-spacing: -0.015em; text-align: center; }
.bdr-answer { margin: 24px 0 18px; padding: 20px 22px; border-radius: var(--r); background: rgba(var(--violet), .14); box-shadow: inset 0 0 0 1px rgba(var(--lilac), .22); color: var(--muted); font-size: 16px; line-height: 25px; }
.bdr-answer b { color: var(--text); }
.bdr-qa { border-radius: 16px; background: var(--panel); box-shadow: inset 0 0 0 1px var(--line); margin-top: 8px; }
.bdr-qa summary { cursor: pointer; list-style: none; padding: 16px 48px 16px 18px; font-weight: 600; font-size: 16px; position: relative; }
.bdr-qa summary::-webkit-details-marker { display: none; }
.bdr-qa summary::after { content: '+'; position: absolute; right: 18px; top: 12px; font-size: 22px; color: rgb(var(--lilac)); }
.bdr-qa[open] summary::after { content: '\2212'; }
.bdr-qa p { padding: 0 18px 16px; color: var(--muted); font-size: 15px; line-height: 23px; }
.bdr-faq-more { text-align: center; color: var(--muted); margin-top: 18px !important; }
.bdr-faq-more a { color: rgb(var(--lilac)); font-weight: 600; }
.bdr-sub { color: var(--muted); font-size: 17px; line-height: 26px; margin-top: 12px !important; }
.bdr-rail-left { grid-area: left; }
.bdr-centre { grid-area: centre; min-width: 0; }
.bdr-rail-right { grid-area: right; display: grid; gap: 16px; }
.bdr-mobtabs, .bdr-ticker { display: none; }

.bdr-panel { background: var(--panel); border-radius: var(--r); padding: 20px; box-shadow: inset 0 0 0 1px var(--line); }
.bdr-rail-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-bottom: 14px; }
.bdr-rail-h { font-family: var(--display); font-size: 21px; line-height: 26px; font-weight: 500; letter-spacing: -0.01em; }

/* The table */
.bdr-centre { --warm: .4; --glow: var(--violet); --glow-2: var(--lilac); }
.bdr-scene.is-break .bdr-centre { --glow: 234, 88, 12; --glow-2: var(--ember); }
.bdr-table-head { display: flex; justify-content: center; color: var(--muted); font-size: 14px; }
.bdr-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.bdr-onair { display: inline-flex; align-items: center; gap: 10px; flex-wrap: wrap; justify-content: center; text-align: center; }
.bdr-onair-pill {
  display: inline-flex; align-items: center; gap: 7px; height: 26px; padding: 0 11px 0 9px; border-radius: 6px;
  background: #e5243b; color: #fff; font: 800 12px/1 var(--body); letter-spacing: .06em; text-transform: uppercase;
  box-shadow: 0 0 22px -4px rgba(229, 36, 59, .9);
}
.bdr-onair-pill i { width: 7px; height: 7px; border-radius: 50%; background: #fff; animation: bdr-rec 1.4s ease-in-out infinite; }
#together { color: var(--text); font-weight: 600; }
.bdr-feed {
  display: flex; align-items: center; justify-content: center; gap: 8px; min-height: 30px; margin-top: 10px !important;
  color: var(--text); font-size: 14px; line-height: 20px; text-align: center;
}
.bdr-feed:empty { visibility: hidden; }
.bdr-feed.is-new { animation: bdr-feed-in .5s cubic-bezier(.2, 1.2, .4, 1); }
.bdr-av-xs { width: 24px; height: 24px; font-size: 10px; }
.bdr-seat-prog {
  position: absolute; inset: -5px; border-radius: 50%; pointer-events: none; --p: 0;
  background: conic-gradient(var(--halo) calc(var(--p) * 360deg), rgba(255, 255, 255, .1) 0);
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 2.5px));
          mask: radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 2.5px));
}
.bdr-seat-prog.is-break { background: conic-gradient(rgb(var(--ember)) calc(var(--p) * 360deg), rgba(255, 255, 255, .1) 0); }
.bdr-sit-cta { display: none; }
@keyframes bdr-rec { 0%, 100% { opacity: 1; } 50% { opacity: .25; } }
@keyframes bdr-feed-in { from { opacity: 0; transform: translateY(8px) scale(.96); } to { opacity: 1; transform: none; } }
.bdr-ring-wrap { position: relative; width: min(100%, 540px); aspect-ratio: 1; margin: 8px auto 0; }
.bdr-motes { position: absolute; inset: -10% -30%; width: 160%; height: 120%; pointer-events: none; z-index: 0; }
.bdr-aura {
  position: absolute; left: 50%; top: 50%; width: 80%; height: 80%; border-radius: 50%; z-index: 0;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle, rgba(var(--glow), .9) 0%, rgba(var(--glow), .3) 34%, rgba(var(--glow), 0) 68%);
  filter: blur(28px); opacity: var(--warm); transition: opacity 2s ease;
  animation: bdr-aura 9s ease-in-out infinite;
}
.bdr-scene.is-break .bdr-aura { animation: bdr-breath 10s linear infinite; }
.bdr-threads { position: absolute; inset: 0; width: 100%; height: 100%; z-index: 1; overflow: visible; }
.bdr-thread { stroke: var(--halo); stroke-width: 1; opacity: .26; stroke-linecap: round; stroke-dasharray: 2 7; animation: bdr-flow 3.2s linear infinite; transition: opacity .3s ease, stroke-width .3s ease; }
.bdr-thread.is-lit { stroke-width: 3; opacity: 1; stroke-dasharray: 6 6; animation-duration: .5s; filter: drop-shadow(0 0 6px var(--halo)); }
.bdr-ring { position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg); z-index: 1; }
.bdr-ring circle { fill: none; stroke-width: 8; }
.bdr-ring-track { stroke: rgba(255, 255, 255, .06); }
.bdr-ring-arc { stroke: rgb(var(--glow-2)); stroke-linecap: round; filter: drop-shadow(0 0 6px rgba(var(--glow-2), .7)); }
.bdr-ring-zone { stroke: rgb(var(--ember)); opacity: .3; }
.bdr-ring-break { stroke: rgb(var(--ember)); stroke-linecap: round; filter: drop-shadow(0 0 6px rgba(var(--ember), .7)); }
.bdr-ripples { position: absolute; inset: 0; z-index: 2; pointer-events: none; }
.bdr-ripple {
  position: absolute; left: 50%; top: 50%; width: 75%; height: 75%; border-radius: 50%;
  border: 2px solid rgba(var(--glow-2), .9); box-shadow: 0 0 24px rgba(var(--glow-2), .5), inset 0 0 24px rgba(var(--glow-2), .3);
  transform: translate(-50%, -50%) scale(.12); animation: bdr-ripple 1.25s cubic-bezier(.2, .7, .3, 1) forwards;
}
.bdr-core { position: absolute; inset: 21%; z-index: 3; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
.bdr-mascot { width: 36%; height: auto; margin-bottom: 2px; animation: bdr-float 6s ease-in-out infinite; filter: drop-shadow(0 10px 26px rgba(var(--glow), .6)); }
.bdr-clock { font-family: var(--display); font-size: clamp(34px, 6vw, 54px); line-height: 1; font-weight: 500; letter-spacing: -0.02em; font-variant-numeric: tabular-nums lining-nums; text-shadow: 0 0 28px rgba(var(--glow-2), .45); }
.bdr-phase { color: var(--muted); font-size: 14px; margin-top: 4px !important; }
.bdr-tally { margin-top: 6px !important; min-height: 20px; font-size: 15px; white-space: nowrap; }
.bdr-mascot-say {
  position: absolute; left: 50%; top: 21%; transform: translateX(-50%); z-index: 6;
  background: #fff; color: #120a1f; font-weight: 600; border-radius: 16px; padding: 9px 14px;
  max-width: 240px; text-align: center; font-size: 13px; line-height: 18px; animation: bdr-pop-in .3s ease-out;
}
.bdr-breath { text-align: center; font-family: var(--display); font-style: italic; font-size: 26px; line-height: 32px; color: rgb(var(--glow-2)); margin-top: 6px !important; }
.bdr-next { text-align: center; color: var(--muted); font-size: 14px; margin-top: 8px !important; }

.bdr-seats { position: absolute; inset: 0; z-index: 4; }
.bdr-seat-av {
  position: absolute; width: 56px; height: 56px; margin: -28px 0 0 -28px; border-radius: 50%;
  border: 3px solid var(--night); display: grid; place-items: center; font: 700 17px var(--body);
  cursor: pointer; padding: 0; transition: transform .2s ease; box-shadow: 0 0 22px -4px var(--halo);
  background-size: cover; background-position: center;
}
.bdr-seat-av::before { content: ''; position: absolute; inset: -9px; border-radius: 50%; border: 2px solid var(--halo); animation: bdr-halo 5s ease-in-out infinite; animation-delay: var(--d, 0s); pointer-events: none; }
.bdr-seat-av:hover { transform: scale(1.1); }
.bdr-seat-av.is-me { cursor: default; width: 64px; height: 64px; margin: -32px 0 0 -32px; }
.bdr-seat-av.is-me::before { border-width: 3px; }
.bdr-seat-av.is-me:hover { transform: none; }
.bdr-seat-av.is-touched { animation: bdr-touch .8s ease-out; }
.bdr-seat-av.is-new { animation: bdr-arrive 1s cubic-bezier(.2, 1.4, .4, 1); }
.bdr-seat-av.is-empty { background: rgba(6, 3, 12, .6); border: 2px dashed rgba(var(--lilac), .7); color: rgb(var(--lilac)); font-size: 28px; font-weight: 300; box-shadow: none; --halo: rgba(196, 181, 253, .8); }
.bdr-seat-more { cursor: default; background: #1a1226; color: var(--muted); font-size: 13px; }
.bdr-seat-name {
  position: absolute; top: calc(100% + 8px); left: 50%; transform: translateX(-50%); white-space: nowrap;
  font: 600 12px/16px var(--body); color: var(--text); background: rgba(6, 3, 12, .82); padding: 2px 8px; border-radius: 999px; pointer-events: none;
}
.bdr-seat-min { color: var(--muted); font-weight: 400; }

.bdr-flights { position: absolute; inset: 0; pointer-events: none; z-index: 5; }
.bdr-flight { position: absolute; font-size: 34px; line-height: 1; transform: translate(-50%, -50%); will-change: transform, opacity; filter: drop-shadow(0 0 10px rgba(255, 255, 255, .45)); }
.bdr-spark { position: absolute; width: 7px; height: 7px; border-radius: 50%; background: rgb(var(--glow-2)); box-shadow: 0 0 8px rgba(var(--glow-2), .9); }
.bdr-bubble {
  position: absolute; transform: translate(-50%, 38px); max-width: 200px; width: max-content;
  background: #fff; color: #120a1f; font: 600 13px/17px var(--body); padding: 8px 12px; border-radius: 14px; text-align: center;
  animation: bdr-pop-in .25s ease-out; transition: opacity .4s ease;
}
.bdr-bubble.is-above { transform: translate(-50%, calc(-100% - 38px)); }
.bdr-bubble.is-out { opacity: 0; }

/* Music: a clear way in, right under the table */
.bdr-music { display: flex; justify-content: center; align-items: center; gap: 8px; flex-wrap: wrap; margin-top: 16px; }
.bdr-music-btn {
  display: inline-flex; align-items: center; gap: 12px; min-height: 56px; padding: 8px 22px 8px 16px; border: 0; border-radius: 999px; cursor: pointer;
  background: rgba(255, 255, 255, .08); color: var(--text); text-align: left; font-family: var(--body);
  box-shadow: inset 0 0 0 1px rgba(var(--lilac), .35); transition: background-color .2s ease, transform .15s ease, box-shadow .2s ease;
}
.bdr-music-btn:hover { background: rgba(255, 255, 255, .13); transform: translateY(-1px); }
.bdr-music-btn:active { transform: scale(.97); }
.bdr-music-btn[aria-pressed="true"] { background: #fff; color: #120a1f; box-shadow: 0 10px 30px -10px rgba(var(--lilac), .9); }
.bdr-music-text { display: flex; flex-direction: column; }
.bdr-music-main { font-weight: 700; font-size: 15px; line-height: 20px; }
.bdr-music-sub { font-size: 12px; line-height: 16px; color: var(--muted); }
.bdr-music-btn[aria-pressed="true"] .bdr-music-sub { color: #4b3d66; }
.bdr-eq { display: inline-flex; align-items: flex-end; gap: 3px; width: 26px; height: 22px; flex: none; }
.bdr-eq i { flex: 1; height: 30%; border-radius: 2px; background: rgb(var(--lilac)); transform-origin: bottom; }
