.bdr-music-btn[aria-pressed="true"] .bdr-eq i:nth-child(2) { animation-delay: -.3s; }
.bdr-music-btn[aria-pressed="true"] .bdr-eq i:nth-child(3) { animation-delay: -.6s; }
.bdr-music-btn[aria-pressed="true"] .bdr-eq i:nth-child(4) { animation-delay: -.15s; }
.bdr-music-btn[aria-pressed="false"] .bdr-eq i:nth-child(1) { height: 45%; }
.bdr-music-btn[aria-pressed="false"] .bdr-eq i:nth-child(2) { height: 80%; }
.bdr-music-btn[aria-pressed="false"] .bdr-eq i:nth-child(3) { height: 60%; }
.bdr-music-btn[aria-pressed="false"] .bdr-eq i:nth-child(4) { height: 35%; }
.bdr-music-more { height: 40px; padding: 0 14px; border: 0; border-radius: 999px; background: transparent; color: var(--muted); font: 600 13px/18px var(--body); cursor: pointer; }
.bdr-music-more:hover { color: var(--text); }
.bdr-centre .bdr-player { width: min(100%, 420px); margin: 14px auto 0; }
@keyframes bdr-eq { 0%, 100% { height: 25%; } 50% { height: 100%; } }

.bdr-reactbar { margin-top: 18px; text-align: center; }
.bdr-emoji-row { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; max-width: 100%; }
.bdr-emoji-btn {
  width: 52px; height: 52px; border: 0; border-radius: 50%; background: var(--panel-2); font-size: 24px; cursor: pointer;
  transition: transform .15s cubic-bezier(.2, 1.4, .4, 1), background-color .15s ease;
}
.bdr-emoji-btn:hover { transform: translateY(-4px) scale(1.15); background: rgba(255, 255, 255, .12); }
.bdr-emoji-btn:active { transform: scale(.9); }
.bdr-reactbar .bdr-quiet { margin-top: 10px !important; font-size: 13px; }
.bdr-scene.is-locked .bdr-emoji-btn { opacity: .5; }
.bdr-scene.is-cooling .bdr-emoji-btn { opacity: .5; pointer-events: none; }

/* Avatars in lists */
.bdr-av { width: 36px; height: 36px; border-radius: 50%; flex: none; display: grid; place-items: center; font-weight: 700; font-size: 13px; background-size: cover; background-position: center; }
.bdr-av-lg { width: 52px; height: 52px; font-size: 17px; }

/* Kind words: the last six, newest on top, fading as they get older. No scrolling. */
.bdr-words { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
.bdr-words li { display: grid; grid-template-columns: 36px 1fr; gap: 10px; align-items: start; animation: bdr-slide .35s ease-out; }
.bdr-words li:nth-child(4) { opacity: .72; }
.bdr-words li:nth-child(5) { opacity: .5; }
.bdr-words li:nth-child(6) { opacity: .3; }
.bdr-word { background: var(--panel-2); border-radius: 4px 16px 16px 16px; padding: 8px 12px; min-width: 0; }
.bdr-word-name { display: block; color: var(--muted); font-size: 12px; line-height: 16px; }
.bdr-word-text { display: block; font-size: 14px; line-height: 20px; }
.bdr-words li.is-emoji .bdr-word { background: transparent; padding: 0 4px; }
.bdr-words li.is-emoji .bdr-word-text { font-size: 26px; line-height: 30px; }
.bdr-composer { margin-top: 16px; padding-top: 16px; border-top: 1px solid var(--line); }
.bdr-tabs { display: flex; background: var(--panel-2); border-radius: 999px; padding: 3px; }
.bdr-tabs button { flex: 1; height: 34px; border: 0; border-radius: 999px; background: transparent; color: var(--muted); font: 600 13px/18px var(--body); cursor: pointer; }
.bdr-tabs button[aria-selected="true"] { background: #fff; color: #120a1f; }
.bdr-phrases { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.bdr-phrase {
  border: 0; background: transparent; color: var(--text); border-radius: 999px; box-shadow: inset 0 0 0 1px var(--line-2);
  padding: 8px 12px; font: 500 13px/18px var(--body); cursor: pointer; text-align: left; transition: background-color .15s ease, transform .15s ease;
}
.bdr-phrase:hover { background: var(--panel-2); }
.bdr-phrase:active { transform: scale(.96); }
.bdr-composer #composer-lock { margin-top: 10px !important; font-size: 13px; }
.bdr-composer.is-locked .bdr-phrase { opacity: .45; }
.bdr-composer.is-cooling .bdr-phrase { opacity: .45; pointer-events: none; }

/* Your seat */
.bdr-form { display: grid; gap: 16px; }
.bdr-field { display: grid; gap: 8px; border: 0; padding: 0; margin: 0; min-width: 0; }
.bdr-field label, .bdr-field legend { font-weight: 600; font-size: 14px; padding: 0; margin-bottom: 8px; }
.bdr-field label { margin-bottom: 0; }
.bdr input:not([type]) {
  height: 48px; border-radius: 14px; border: 0; box-shadow: inset 0 0 0 1px var(--line-2); width: 100%;
  background: rgba(0, 0, 0, .35); color: var(--text); padding: 0 14px; font: 400 16px/20px var(--body);
}
.bdr input::placeholder { color: var(--faint); }
.bdr-pic-row { display: grid; grid-template-columns: repeat(auto-fill, minmax(44px, 1fr)); gap: 8px; }
.bdr-pic-more { margin-top: 10px; }
.bdr-pic-more summary { color: var(--muted); font-size: 13px; cursor: pointer; list-style: none; }
.bdr-pic-more summary::-webkit-details-marker { display: none; }
.bdr-pic-more summary::after { content: ' +'; }
.bdr-pic-more[open] summary::after { content: ' \2212'; }
.bdr-pic-more .bdr-pic-row { margin-top: 10px; }
.bdr-hue { position: relative; display: block; }
.bdr-hue input { position: absolute; opacity: 0; width: 0; height: 0; }
.bdr-hue span {
  display: block; width: 100%; max-width: 52px; aspect-ratio: 1; border-radius: 50%; cursor: pointer; margin: 0 auto;
  background-size: cover; background-position: center; box-shadow: 0 0 0 2px transparent; transition: transform .15s ease, box-shadow .15s ease;
}
.bdr-hue span:hover { transform: scale(1.07); }
.bdr-hue input:checked + span { box-shadow: 0 0 0 2px #120b1d, 0 0 0 4px #fff; }
.bdr-seated-row { display: flex; gap: 12px; align-items: center; }
.bdr-seated-text { min-width: 0; flex: 1; }
.bdr-seated-name { font-weight: 700; font-size: 17px; line-height: 24px; }
.bdr-seated-task { color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bdr-seated-sessions { text-align: right; display: flex; flex-direction: column; }
.bdr-seated-sessions .num { font-family: var(--display); font-size: 30px; line-height: 32px; font-weight: 500; }
.bdr-seated-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }

/* Focus length */
.bdr-field-label { font-weight: 600; font-size: 14px; }
.bdr-lens { display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px; }
.bdr-len {
  height: 44px; border: 0; border-radius: 14px; background: transparent; box-shadow: inset 0 0 0 1px var(--line-2);
  color: var(--text); font: 600 13px/18px var(--body); cursor: pointer; transition: background-color .15s ease, transform .15s ease;
  white-space: nowrap; padding: 0 2px;
}
.bdr-len:hover { background: var(--panel-2); }
.bdr-len:active { transform: scale(.96); }
.bdr-len[aria-pressed="true"] { background: #fff; color: #120a1f; box-shadow: none; }
.bdr-seated-len { margin-top: 16px; display: grid; gap: 8px; }
.bdr-seated-len .bdr-len { height: 38px; font-size: 13px; }

/* Radio */
.bdr-station-group + .bdr-station-group { margin-top: 12px; }
.bdr-station-label { color: var(--faint); font-size: 12px; margin-bottom: 8px !important; }
.bdr-stations-row { display: flex; flex-wrap: wrap; gap: 6px; }
.bdr-station {
  height: 36px; padding: 0 13px; border: 0; border-radius: 999px; background: transparent; box-shadow: inset 0 0 0 1px var(--line-2);
  color: var(--text); font: 500 13px/18px var(--body); cursor: pointer; white-space: nowrap; transition: background-color .15s ease, transform .15s ease;
}
.bdr-station:hover { background: var(--panel-2); }
.bdr-station:active { transform: scale(.96); }
.bdr-station[aria-pressed="true"] { background: #fff; color: #120a1f; box-shadow: none; }
.bdr-station.is-foco { box-shadow: inset 0 0 0 1px rgba(var(--lilac), .45); }
.bdr-station.is-foco[aria-pressed="true"] { box-shadow: none; }
.bdr-station:disabled { opacity: .35; cursor: not-allowed; text-decoration: line-through; }
.bdr-player { margin-top: 14px; aspect-ratio: 16 / 9; min-height: 200px; border-radius: 14px; overflow: hidden; background: #000; }
.bdr-player iframe, .bdr-player > div { width: 100%; height: 100%; border: 0; display: block; }
.bdr-radio-sync { color: rgb(var(--lilac)); font-size: 13px; margin-top: 10px !important; }

/* People */
.bdr-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
.bdr-person {
  display: grid; grid-template-columns: 36px 1fr auto; gap: 10px; align-items: center; width: 100%;
  min-height: 54px; padding: 6px 8px; background: transparent; border: 0; border-radius: 12px; color: inherit; text-align: left; font: inherit; cursor: pointer;
}
.bdr-person:hover { background: var(--panel-2); }
.bdr-person.is-me { cursor: default; }
.bdr-person.is-me:hover { background: transparent; }
.bdr-person-mid { min-width: 0; display: flex; flex-direction: column; }
.bdr-person-name { font-weight: 600; font-size: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.bdr-person-task { color: var(--muted); font-size: 13px; line-height: 18px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.bdr-person-side { text-align: right; color: var(--muted); font-size: 13px; white-space: nowrap; }

/* How it works */
.bdr-how { max-width: 1100px; margin: 80px auto 0; text-align: center; }
.bdr-how h2, .bdr-get h2 { font-family: var(--display); font-weight: 500; font-size: clamp(28px, 3.4vw, 40px); line-height: 1.1; letter-spacing: -0.015em; }
.bdr-how-list { list-style: none; padding: 0; margin: 28px 0 0; display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; text-align: left; }
.bdr-how-list li { background: var(--panel); box-shadow: inset 0 0 0 1px var(--line); border-radius: var(--r); padding: 22px; color: var(--muted); }
.bdr-how-list b { display: block; color: var(--text); font-size: 16px; margin-bottom: 6px; }

/* Get FOCO */
.bdr-get {
  max-width: 1100px; margin: 24px auto 0; display: grid; grid-template-columns: 1fr auto; gap: 32px; align-items: center;
  background: linear-gradient(135deg, rgba(var(--violet), .24), rgba(var(--violet), .06)); box-shadow: inset 0 0 0 1px rgba(var(--lilac), .2);
  border-radius: 28px; padding: clamp(24px, 4vw, 44px);
}
.bdr-get-text p { color: var(--muted); font-size: 16px; line-height: 24px; margin-top: 10px !important; max-width: 54ch; }
.bdr-get-btns { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 22px; }
.bdr-store {
  display: grid; text-decoration: none; background: #000; color: #fff; border-radius: 14px; padding: 10px 18px;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .25); min-width: 200px; transition: transform .15s ease, box-shadow .15s ease;
}
.bdr-store:hover { transform: translateY(-2px); box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .5); }
.bdr-store.is-best { box-shadow: inset 0 0 0 2px #fff, 0 10px 30px -10px rgba(var(--lilac), .9); }
.bdr-store-small { font-size: 11px; line-height: 14px; color: #cfc8e6; }
.bdr-store-big { font-size: 21px; line-height: 26px; font-weight: 700; }
.bdr-qr { margin: 0; text-align: center; }
.bdr-qr-code { width: 168px; height: 168px; background: #fff; border-radius: 18px; padding: 12px; }
.bdr-qr-code svg, .bdr-qr-code img { width: 100%; height: 100%; display: block; }
.bdr-qr figcaption { color: var(--muted); font-size: 13px; margin-top: 10px; max-width: 168px; }

/* Popover, toasts, dialogs */
.bdr-pop { position: fixed; z-index: 20; width: 280px; background: #1a1226; border-radius: 18px; padding: 16px; box-shadow: 0 18px 48px rgba(0, 0, 0, .6), inset 0 0 0 1px var(--line-2); animation: bdr-pop-in .15s ease; }
.bdr-pop-h { font-weight: 700; font-size: 16px; }
.bdr-pop-task { color: var(--muted); margin: 4px 0 8px !important; }
.bdr-pop .bdr-btn-text { padding: 0; height: 32px; }
.bdr-toasts { position: fixed; z-index: 30; left: 50%; bottom: calc(20px + env(safe-area-inset-bottom)); transform: translateX(-50%); display: grid; gap: 8px; width: min(420px, calc(100% - 32px)); }
.bdr-toast { display: grid; grid-template-columns: 36px 1fr; gap: 12px; align-items: center; background: #1a1226; border-radius: 16px; padding: 12px 14px; box-shadow: 0 14px 36px rgba(0, 0, 0, .5), inset 0 0 0 1px var(--line-2); animation: bdr-slide .25s ease-out; }
.bdr-modal { position: fixed; inset: 0; z-index: 40; background: rgba(6, 3, 12, .86); display: grid; place-items: center; padding: 16px; overflow-y: auto; }
.bdr-modal-box { background: #120b1d; border-radius: 26px; padding: 30px; width: min(460px, 100%); text-align: center; box-shadow: inset 0 0 0 1px var(--line-2); animation: bdr-pop-in .25s ease-out; }
.bdr-modal-box h2 { font-family: var(--display); font-weight: 500; font-size: 30px; line-height: 36px; margin-top: 10px; }
.bdr-modal-box h2 em { font-style: italic; font-weight: 400; color: rgb(var(--lilac)); }
.bdr-recap-mascot { width: 104px; height: auto; }
.bdr-recap-line { color: var(--muted); margin-top: 10px !important; font-size: 16px; line-height: 24px; }
.bdr-recap-actions { display: grid; gap: 8px; margin-top: 22px; }
.bdr-recap-app { color: var(--muted); margin-top: 16px !important; font-size: 14px; }
.bdr-recap-app a { color: rgb(var(--lilac)); font-weight: 600; }
.bdr-share-box { text-align: left; width: min(440px, 100%); padding: 22px; }
.bdr-share-head { display: flex; align-items: center; justify-content: space-between; }
.bdr-share-head h2 { margin: 0; font-size: 26px; }
.bdr-close { width: 40px; height: 40px; border: 0; border-radius: 50%; background: var(--panel-2); color: var(--text); font-size: 24px; line-height: 1; cursor: pointer; }
.bdr-share-opts { display: flex; gap: 8px; margin: 14px 0; flex-wrap: wrap; }
.bdr-seg { display: inline-flex; background: var(--panel-2); border-radius: 999px; padding: 3px; }
.bdr-seg button { height: 34px; padding: 0 14px; border: 0; border-radius: 999px; background: transparent; color: var(--muted); font: 600 13px/18px var(--body); cursor: pointer; }
.bdr-seg button[aria-pressed="true"] { background: #fff; color: #120a1f; }
.bdr-share-preview { display: grid; place-items: center; background: #000; border-radius: 18px; padding: 12px; margin-bottom: 14px; min-height: 200px; }
.bdr-share-img { display: block; max-width: 100%; max-height: 46vh; height: auto; border-radius: 10px; }
.bdr-share-row { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.bdr-share-tip { color: var(--muted); font-size: 13px; line-height: 19px; margin-top: 12px !important; }
.bdr-share-tip b { color: var(--text); }

.bdr-credits { max-width: 1100px; margin: 32px auto 0 !important; color: var(--faint); font-size: 12px; line-height: 18px; text-align: center; }
.bdr-credits a { color: var(--muted); }
.bdr-noscript { padding: 24px; color: var(--muted); }

@keyframes bdr-ping { 0% { transform: scale(.6); opacity: .9; } 100% { transform: scale(1.8); opacity: 0; } }
@keyframes bdr-aura { 0%, 100% { transform: translate(-50%, -50%) scale(.94); } 50% { transform: translate(-50%, -50%) scale(1.06); } }
@keyframes bdr-breath { 0% { transform: translate(-50%, -50%) scale(.82); } 40% { transform: translate(-50%, -50%) scale(1.14); } 100% { transform: translate(-50%, -50%) scale(.82); } }
@keyframes bdr-flow { to { stroke-dashoffset: -18; } }
@keyframes bdr-halo { 0%, 100% { transform: scale(.9); opacity: .12; } 50% { transform: scale(1.12); opacity: .8; } }
@keyframes bdr-touch { 0% { transform: scale(1); filter: brightness(1); } 35% { transform: scale(1.18); filter: brightness(1.4); } 100% { transform: scale(1); filter: brightness(1); } }
@keyframes bdr-arrive { 0% { transform: scale(.3); opacity: 0; } 60% { opacity: 1; } 100% { transform: scale(1); opacity: 1; } }
@keyframes bdr-ripple { 0% { transform: translate(-50%, -50%) scale(.12); opacity: 1; } 100% { transform: translate(-50%, -50%) scale(1.12); opacity: 0; } }
@keyframes bdr-float { 0%, 100% { translate: 0 0; } 50% { translate: 0 -6px; } }
@keyframes bdr-pop-in { from { opacity: 0; scale: .92; } to { opacity: 1; scale: 1; } }
@keyframes bdr-slide { from { opacity: 0; translate: 0 8px; } to { opacity: 1; translate: 0 0; } }

/* Tablets and small laptops: the table on top, the two rails side by side under it */
@media (max-width: 1180px) {
  .bdr-scene { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); grid-template-areas: "intro intro" "centre centre" "left right"; }
}
/* Phones: the table, then tabs that switch one panel at a time */
@media (max-width: 760px) {
  .bdr-bar { height: 60px; }
  .bdr-live { display: none; }
  .bdr-bar-get { height: 36px; padding: 0 14px; margin-left: auto; }
  .bdr-scene { grid-template-columns: minmax(0, 1fr); grid-template-areas: "intro" "centre" "panels"; gap: 16px; }
  .bdr-intro { padding-top: 4px; }
  .bdr-intro h1 { font-size: 34px; }
  .bdr-sub { display: none; }
  .bdr-scene.is-locked .bdr-sit-cta { display: flex; margin-top: 14px; }
  .bdr-scene.is-locked .bdr-reactbar { display: none; }
  .bdr-feed { font-size: 13px; }
  .bdr-sub { font-size: 15px; line-height: 22px; }
  .bdr-rail-left, .bdr-rail-right { grid-area: panels; }
  .bdr-rail-right { display: block; }
  /* An app-like bar fixed to the bottom, always in reach of a thumb */
  .bdr { padding-bottom: calc(96px + env(safe-area-inset-bottom)); }
  .bdr-mobtabs {
    position: fixed; left: 10px; right: 10px; bottom: calc(10px + env(safe-area-inset-bottom)); z-index: 25;
    display: grid; grid-template-columns: repeat(4, 1fr); gap: 4px; padding: 6px;
    background: rgba(18, 11, 29, .96); border-radius: 22px; box-shadow: 0 12px 40px rgba(0, 0, 0, .6), inset 0 0 0 1px var(--line-2);
  }
  .bdr-mobtabs button {
    position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px;
    height: 54px; border: 0; border-radius: 16px; background: transparent; color: var(--muted); font: 600 11px/14px var(--body); cursor: pointer;
  }
  .bdr-mobtabs svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  .bdr-mobtabs button[aria-pressed="true"] { background: rgba(255, 255, 255, .1); color: #fff; }
  .bdr-badge {
    position: absolute; top: 5px; left: calc(50% + 6px); min-width: 18px; height: 18px; padding: 0 5px; border-radius: 999px;
    background: #fb923c; color: #1a0d00; font: 700 11px/18px var(--body);
  }
  .bdr-badge-soft { background: rgba(var(--lilac), .9); color: #120a1f; }
  .bdr-toasts { bottom: calc(90px + env(safe-area-inset-bottom)); }
  .bdr-ticker {
    display: flex; align-items: center; gap: 10px; width: 100%; margin: 14px auto 0; padding: 8px 10px 8px 8px; border: 0; border-radius: 18px;
    background: var(--panel-2); color: var(--text); text-align: left; font: 500 14px/19px var(--body); cursor: pointer;
  }
  .bdr-ticker.is-new { animation: bdr-slide .35s ease-out; }
  .bdr-ticker-text { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .bdr-ticker-text b { font-weight: 700; }
  .bdr-ticker-go { color: rgb(var(--lilac)); font-weight: 700; font-size: 13px; flex: none; }
  .bdr-panel { display: none; }
  .bdr-panel.is-shown { display: block; }
  .bdr-ring-wrap { width: min(100%, 440px); }
  .bdr-motes { inset: -6% 0; width: 100%; height: 112%; }
  .bdr-seat-av { width: 46px; height: 46px; margin: -23px 0 0 -23px; font-size: 14px; }
  .bdr-seat-av.is-me { width: 52px; height: 52px; margin: -26px 0 0 -26px; }
  .bdr-seat-name { font-size: 11px; padding: 1px 6px; top: calc(100% + 5px); }
  .bdr-emoji-row { gap: 12px; max-width: 268px; margin: 0 auto; }
  .bdr-emoji-btn { width: 58px; height: 58px; font-size: 26px; }
  .bdr-how { margin-top: 56px; }
  .bdr-how-list { grid-template-columns: 1fr; }
  .bdr-get { grid-template-columns: 1fr; text-align: center; }
  .bdr-get-text p { margin-inline: auto !important; }
  .bdr-get-btns { justify-content: center; }
  .bdr-store { flex: 1 1 200px; }
  .bdr-qr { display: none; }
  .bdr-pop { left: 16px !important; right: 16px; width: auto; top: auto !important; bottom: calc(16px + env(safe-area-inset-bottom)); }
  .bdr-modal { place-items: end center; padding: 0; }
  .bdr-modal-box { border-radius: 26px 26px 0 0; width: 100%; padding-bottom: calc(24px + env(safe-area-inset-bottom)); max-height: 94vh; overflow-y: auto; }
  .bdr-share-img { max-height: 38vh; }
}
@media (max-width: 360px) {
  .bdr-emoji-row { gap: 10px; max-width: 238px; }
  .bdr-emoji-btn { width: 52px; height: 52px; }
  .bdr-mobtabs button { font-size: 12px; }
}
@media (hover: none) and (min-width: 761px) {
  .bdr-qr { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .bdr *, .bdr *::before, .bdr *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

/* Share from anywhere: the top bar and under the table */
.bdr-bar-share { height: 40px; padding: 0 16px 0 13px; gap: 7px; }
.bdr-bar-share svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.bdr-invite-inline { color: rgb(var(--lilac)); }

/* Emoji buttons: perfect circles, the glyph dead centre */
