@media (max-width: 760px) {
  .bdr-bar { gap: 8px; }
  .bdr-bar-share { height: 36px; padding: 0 12px 0 10px; }
  .bdr-bar-get { margin-left: 0; }
  .bdr-brand { margin-right: auto; }
}
@media (max-width: 380px) {
  .bdr-bar-share span { display: none; }
  .bdr-bar-share { width: 36px; padding: 0; }
}

/* ---------- Recording mode (?tv): a fixed 1920x1080 stage for YouTube ---------- */
html.is-tv, html.is-tv body { width: 1920px; height: 1080px; overflow: hidden; }
