html.is-tv .bdr-person-side { font-size: 15px; }
html.is-tv .bdr-person .bdr-av { width: 44px; height: 44px; }
html.is-tv .bdr-person { grid-template-columns: 44px 1fr auto; }
.bdr-tv-badge {
  position: absolute; left: 56px; bottom: 26px; display: flex; align-items: center; gap: 10px;
  color: var(--muted); font-size: 16px; line-height: 20px;
}
.bdr-tv-badge i { width: 9px; height: 9px; border-radius: 50%; background: #e5243b; }
.bdr-tv-badge b { color: var(--text); }
.bdr-tv-title { position: absolute; left: 50%; top: 26px; transform: translateX(-50%); text-align: center; }
.bdr-tv-title span { display: block; font-family: var(--display); font-size: 40px; line-height: 44px; font-weight: 500; letter-spacing: -0.02em; }
