.bdr-tv-how ol { margin: 0; padding: 0; list-style: none; counter-reset: s; }
.bdr-tv-how li { counter-increment: s; position: relative; padding: 10px 0 10px 46px; font-size: 18px; line-height: 25px; color: var(--muted); }
.bdr-tv-how li::before { content: counter(s); position: absolute; left: 0; top: 9px; width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; font-weight: 800; font-size: 15px; color: #fff; background: rgba(var(--violet), .55); }
